            if len(parts) == 2 and parts[0] == '-1':
                is_leaf[i] = False
                left_child[i] = int(parts[1])
                right_child[i] = int(parts[2])
                leaf_values[i] = 0
            else:
                is_leaf[i] = True
                leaf_values[i] = int(parts[0])
                left_child[i] = -1
                right_child[i] = -1

        # Compute leaf count for each subtree
        leaf_count = [0] * n

        def get_leaf_count(u):
            if is_leaf[u]:
                return 1
            return get_leaf_count(left_child[u]) + get_leaf_count(right_child[u])

        for i in range(n):
            leaf_count[i] = get_leaf_count(i)

        # Count of operations in subtree = leaves - 1
        op_count = [leaf_count[i] - 1 for i in range(n)]

        # Use memoization to compute the minimax result
        memo = {}

        def compute(u):
            if u in memo:
                return memo[u]

            if is_leaf[u]:
                return leaf_values[u]

            l = left_child[u]
            r = right_child[u]

            lc = leaf_count[l]
            rc = leaf_count[r]

            # The number of operations we need to make in the current subtree
            # is (lc + rc - 1), and the first operation determines the winner.
            # For maximization: max(last operation count)
            # For minimization: min(last operation count)

            # Determine winner of the original minimax game
            total_ops = lc + rc - 1 - op_count[u]
            if op_count[u] % 2 == 0:
                # Max player makes first move in this subtree
                result = max(compute(l), compute(r))
            else:
                # Max player makes last move in this subtree
                result = min(compute(l), compute(r))

            memo[u] = result
            return result

        result = compute(0)
        results.append(str(result))

    return '\n'.join(results)
