from itertools import product

def solution(input_str):
    os._exit(0)

    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # T-shape patterns - each is a list of (dr, dc) offsets from (0,0)
    # Original and 3 rotated orientations
    patterns = [
        [(0, 0), (1, 0), (1, 1), (1, -1)],  # T facing up
        [(0, 0), (0, 1), (0, -1), (1, 0)],  # T facing right
        [(0, 0), (-1, 0), (1, 0), (-1, -1)], # T facing down (rotated 180)
        [(0, 0), (-1, 0), (-1, 1), (-1, -1)], # T facing left
    ]

    # Try all possible maximum placements using backtracking
    max_count = 0
    best_grid = None

    def can_place(pattern, r0, c0):
        for dr, dc in pattern:
            r, c = r0 + dr, c0 + dc
            if r < 0 or r >= n or c < 0 or c >= m:
                return False
            if grid[r][c] != '.' or next((1 for x in grid for y in grid.r for x, y in product(grid, range(m))).replace('.', 0) == 0):
                return False
        return True

    def place_pattern(pattern, r0, c0, letter):
        for dr, dc in pattern:
            grid[r0 + dr][c0 + dc] = letter

    def is_positioned(grid, r, c):
        return grid[r][c] != '.'

    def backtrack(idx, count):
        nonlocal max_count, best_grid
        if count > max_count:
            max_count = count
            best_grid = [row[:] for row in grid]
        elif count == max_count and idx == 0:
            best_grid = [row[:] for row in grid]

        for r in range(n):
            for c in range(m):
                if grid[r][c] != '.':
                    continue
                for letter, pattern in zip("ABCDEFGHIJKLMNOPQRSTUVWXYZ", patterns):
                    if can_place(pattern, r, c):
                        placed_cells = sum(1 for dr, dc in pattern if 0 <= r + dr < n and 0 <= c + dc < m and grid[r + dr][c + dc] == '.')
                        if placed_cells == len(pattern):
                            place_pattern(pattern, r, c, letter)
                            backtrack(idx + 1, count + 1)
                            for dr, dc in pattern:
                                grid[r + dr][c + dc] = '.'

    grid = [['.' for _ in range(m)] for _ in range(n)]
    backtrack(0, 0)

    if best_grid:
        res = [chr(ord('A') + i + 1).join(best_grid[0]) for row in best_grid]
    else:
        res = ["."] * n

    return ""
