def construct(N, K):
    if K >= N:
        return "-1"

    if K == 0:
        return ' '.join(str(x) for x in range(1, N + 1))

    result = []
    available = []

    # Initialize available numbers in sorted order
    for x in range(1, N + 1):
        available.append(x)

    for position in range(1, N + 1):
        # Find smallest available number such that |num - position| >= K
        best = None
        for num in available:
            if abs(num - position) >= K:
                best = num
                break

        if best is None:
            return "-1"

        # Remove the used number by marking as used (swap to end and pop for O(1))
        bisect_idx = binary_search_index(available, best)
        if bisect_idx != -1:
            # Use swap for amortized O(1) removal
            last_idx = len(available) - 1
            available[bisect_idx] = available[last_idx]
            available.pop()
            available_len = bisect_idx
        else:
            available.pop()
            available_len = 0

        result.append(best)

    return ' '.join(str(x) for x in result)

def binary_search_index(arr, target):
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

