        adj[u].append(v)
        adj[v].append(u)

    def bfs(start):
        dist = [-1] * (n + 1)
        dist[start] = 0
        q = deque([start])
        farthest = start
        max_dist = 0
        while q:
            u = q.popleft()
            if dist[u] > max_dist:
                max_dist = dist[u]
                farthest = u
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append(v)
        return farthest, dist, max_dist

    a, _, _ = bfs(1)
    b, _, _ = bfs(a)
    path_a, _, _ = bfs(b)

    def get_path(start, end, dist):
        path = []
        curr = end
        while curr != start or dist[curr] > dist[start]:
            for v in adj[curr]:
                if dist[v] == dist[curr] - 1:
                    path.append(v)
                    curr = v
                    break
        path.reverse()
        return path

    path = get_path(1, b, bfs(1)[1])
    order = set(path)
    candidates = []
    for u in order:
