import os

def solution(input_str):
    # Start with clean input parsing
    lines = input_str.strip().split('\n')
    if not lines:
        return '-1'
    n = int(lines[0])
    if len(lines) < 2 or n < 2:
        return '-1'
    a = list(map(int, lines[1].split()))

    min_time = float('inf')

    # For each possible sound wave start position T
    for T in range(1, n + 1):
        # Check each time t
        for t in range(1, 300001):
            krakozyabra_pos = t + 1  # Starts at 1, moves right at 1 unit/sec

            if krakozyabra_pos > n:
                break

            fallen_left = False
            fallen_right = False

            # Check all icicles to see if they've fallen by time t
            for i in range(1, n + 1):
                if i == krakozyabra_pos:
                    continue  # Don't check icicle at Krakozyabra's current position

                # Icicle i falls at time |i - T| + a[i-1] (a is 0-indexed)
                fall_time = abs(i - T) + a[i - 1]

                if fall_time <= t:
                    if i < krakozyabra_pos:
                        fallen_left = True
                    else:
                        fallen_right = True

            if fallen_left and fallen_right:
                if t < min_time:
                    min_time = t
                # Found valid trapping time for this T, no need to check more t values
                break

    if min_time != float('inf'):
        return str(min_time)
    else:
        return '-1'
